<?php
require_once __DIR__.'/../config/siya-news-drive.php';
app_method('GET');$user=app_user();if(!app_can($user,'news_producer'))app_fail('ไม่มีสิทธิ์จัดทำวารสาร',403);
$newsId=filter_var($_GET['id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if(!$newsId)app_fail('รหัสข่าวไม่ถูกต้อง');
$pdo=app_pdo();$q=$pdo->prepare("SELECT n.*,COALESCE(u.User_Name,CONCAT('สมาชิก #',n.owner_id)) owner_name FROM eoffice_siya_news n LEFT JOIN t_user u ON u.User_Id=n.owner_id WHERE n.id=? AND n.status='approved'");$q->execute([(int)$newsId]);$news=$q->fetch();if(!$news)app_fail('ไม่พบข่าวที่ผ่านตรวจแล้ว',404);
$q=$pdo->prepare('SELECT snapshot FROM eoffice_siya_news_revisions WHERE news_id=? AND version=?');$q->execute([(int)$newsId,(int)$news['approved_version']]);$snapshot=$q->fetchColumn();$snapshot=is_string($snapshot)?json_decode($snapshot,true,32,JSON_THROW_ON_ERROR):null;if(!is_array($snapshot)||!is_array($snapshot['images']??null))app_fail('ไม่พบเวอร์ชันข่าวที่ผ่านตรวจแล้ว',503);
if(!class_exists(ZipArchive::class))app_fail('เซิร์ฟเวอร์ยังไม่รองรับการสร้างไฟล์ ZIP',503);
$tmp=tempnam(app_siya_news_root(),'export-');if($tmp===false)app_fail('ไม่สามารถสร้างชุดดาวน์โหลดได้',503);$exportTemps=[];$zip=new ZipArchive();
try{
    @chmod($tmp,0600);if($zip->open($tmp,ZipArchive::CREATE|ZipArchive::OVERWRITE)!==true)throw new RuntimeException('ZIP creation failed');
    $text="SIYA NEWS — ข้อมูลข่าวสำหรับจัดทำวารสาร\n".'หัวข้อ: '.($snapshot['title']??'')."\n".'วันที่กิจกรรม: '.($snapshot['event_date']??'ไม่ระบุ')."\n".'สถานที่: '.($snapshot['location']??'')."\n".'กลุ่มงาน: '.($snapshot['department']??'')."\n".'ผู้ส่ง: '.$news['owner_name']."\n".'เวอร์ชันผ่านตรวจ: '.(int)$news['approved_version']."\n\n".($snapshot['body']??'')."\n";
    if(!$zip->addFromString('ข่าว.txt',"\xEF\xBB\xBF".$text))throw new RuntimeException('ZIP text write failed');
    $csvRow=static function(array $values): string {return implode(',',array_map(static function($value): string {$value=(string)$value;if(preg_match('/^\s*[=+@-]/u',$value))$value="'".$value;return '"'.str_replace('"','""',$value).'"';},$values))."\r\n";};
    $manifest=$csvRow(['ลำดับ','ไฟล์','คำบรรยาย','เครดิตภาพ']);
    $approvedImages=$snapshot['images']??[];if(!is_array($approvedImages)||count($approvedImages)>10)throw new RuntimeException('Invalid approved image manifest');$total=0;
    foreach(array_values($approvedImages) as $index=>$imageMeta){$imageId=is_array($imageMeta)?($imageMeta['id']??''):$imageMeta;if(!is_string($imageId)||!preg_match('/^[a-f0-9]{32}$/D',$imageId))throw new RuntimeException('Invalid approved image reference');$q=$pdo->prepare('SELECT * FROM eoffice_siya_news_images WHERE id=? AND news_id=?');$q->execute([$imageId,(int)$newsId]);$image=$q->fetch();if(!$image)throw new RuntimeException('Approved image reference unavailable');$total+=(int)$image['bytes'];if($total>250*1024*1024)throw new RuntimeException('Approved image set too large');$source=app_siya_news_materialize_image($image);$exportTemps[]=$source;$ext=$image['extension'];$name=sprintf('images/%02d-%s.%s',$index+1,$imageId,$ext);if(!$zip->addFile($source,$name))throw new RuntimeException('ZIP image write failed');$meta=is_array($imageMeta)?$imageMeta:$image;$manifest.=$csvRow([$index+1,$name,$meta['caption']??'',$meta['credit']??'']);}
    if(!$zip->addFromString('รายการภาพ.csv',"\xEF\xBB\xBF".$manifest))throw new RuntimeException('ZIP manifest write failed');if(!$zip->close())throw new RuntimeException('ZIP finalization failed');app_audit('siya_news.export',$user,(int)$newsId);
}catch(Throwable $e){@$zip->close();foreach($exportTemps as $file)@unlink($file);@unlink($tmp);error_log('SIYA NEWS export failed ('.get_class($e).')');if($e instanceof AppSiyaNewsError)app_fail($e->getMessage(),$e->status);app_fail('สร้างชุดดาวน์โหลดไม่สำเร็จ กรุณาลองใหม่',503);}
$safe=preg_replace('/[^\pL\pN_-]/u','_',mb_substr((string)$snapshot['title'],0,80))?:'siya-news';header('Content-Type: application/zip');header('Content-Length: '.filesize($tmp));header('Content-Disposition: attachment; filename="siya-news-'.$newsId.'.zip"; filename*=UTF-8\'\''.rawurlencode($safe.'-'.$newsId.'.zip'));header('Cache-Control: private, no-store, max-age=0');readfile($tmp);@unlink($tmp);foreach($exportTemps as $file)@unlink($file);
